58	/// Compute the effective mana cost of a spell after applying cost reduction effects.
59	/// Returns a reduced ManaCost (generic portion lowered, colored requirements unchanged).
60	pub fn effective_spell_cost(state: &GameState, registry: &CardRegistry, card_id: CardId, base_cost: &ManaCost, caster: PlayerId) -> ManaCost {
61	    use crate::types::{ContinuousEffect, SpellFilter};
62	
63	    // Check if the card has a custom cost modification (e.g., Blasphemous Act).
64	    if let Some(behavior) = registry.get(card_id) {
65	        if let Some(modified) = behavior.modified_cost(state, registry) {
66	            return modified;
67	        }
68	    }
69	
70	    let card_data = registry.card_data(card_id);
