50	#[test]
51	fn clifftop_retreat_enters_untapped_with_mountain() {
52	    let reg = registry();
53	    let mut state = game_at_step(Step::PrecombatMain, P0);
54	
55	    // Put a Mountain on the battlefield.
56	    let mountain_id = reg.get_id_by_name("Mountain").unwrap();
57	    let mtn = state.create_object(mountain_id, P0, Zone::Battlefield, None, None);
58	    state.get_object_mut(mtn).unwrap().name = "Mountain".into();
59	    state.get_object_mut(mtn).unwrap().subtypes = vec!["Mountain".into()];
60	
61	    // Play Clifftop Retreat.
62	    let retreat = spell_in_hand(&mut state, &reg, "Clifftop Retreat", P0);
63	    state.get_player_mut(P0).land_plays_remaining = 1;
64	
65	    let legal = engine::legal_actions(&state, &reg);
66	    let play = legal.actions.iter().find(|a| matches!(a, Action::PlayLand { object_id } if *object_id == retreat)).unwrap();
67	    state = engine::submit_action(&state, play, &reg);
68	
69	    mtg_engine::triggers::collect_triggers(&mut state, &reg);
70	    mtg_engine::triggers::resolve_next_trigger(&mut state, &reg);
71	
72	    assert!(!state.get_object(retreat).unwrap().tapped, "Should enter untapped with Mountain on battlefield");
73	}
